import os, sys, traceback, warnings
import numpy as np
import pandas as pd

warnings.simplefilter("ignore")

memfs_arg = sys.argv[1]           # "None" | "True" | "False"
pb = sys.argv[2] == "1"
nbw = int(sys.argv[3])
only = sys.argv[4] if len(sys.argv) > 4 else None

use_memory_fs = {"None": None, "True": True, "False": False}[memfs_arg]

from pandarallel import pandarallel
pandarallel.initialize(nb_workers=nbw, progress_bar=pb, use_memory_fs=use_memory_fs, verbose=0)


def describe(o):
    if isinstance(o, pd.DataFrame):
        return f"DF shape={o.shape} dtypes={list(o.dtypes.astype(str))} idx={list(o.index)[:6]} cols={list(o.columns)[:8]}"
    if isinstance(o, pd.Series):
        return f"SER len={len(o)} dtype={o.dtype} idx={list(o.index)[:6]} head={list(o.head(4))}"
    return f"{type(o).__name__}: {o!r}"


def cmp(name, seq_call, par_call):
    try:
        seq = seq_call()
        seq_err = None
    except Exception as e:
        seq, seq_err = None, e
    try:
        par = par_call()
        par_err = None
    except Exception as e:
        par, par_err = None, e
        par_tb = traceback.format_exc()

    if seq_err is not None and par_err is not None:
        same = type(seq_err) is type(par_err)
        print(f"[{'BOTH-RAISE-OK' if same else 'RAISE-TYPE-DIFF'}] {name}: seq={type(seq_err).__name__}({seq_err}) par={type(par_err).__name__}({par_err})")
        return
    if seq_err is not None:
        print(f"[SEQ-ONLY-RAISE] {name}: seq raised {type(seq_err).__name__}({seq_err}); par returned {describe(par)}")
        return
    if par_err is not None:
        print(f"[PAR-ONLY-RAISE] {name}: seq returned {describe(seq)}; par raised {type(par_err).__name__}({par_err})")
        print("    " + par_tb.strip().replace("\n", "\n    ")[-1500:])
        return

    problems = []
    if type(seq) is not type(par):
        problems.append(f"type {type(seq).__name__} != {type(par).__name__}")
    if not (hasattr(seq, "equals") and hasattr(par, "equals")):
        if seq != par:
            problems.append("scalar mismatch")
    else:
        if not seq.equals(par):
            problems.append("NOT .equals()")
        if isinstance(seq, pd.DataFrame) and isinstance(par, pd.DataFrame):
            if not seq.index.equals(par.index):
                problems.append("index differs")
            if not seq.columns.equals(par.columns):
                problems.append("columns differ")
            if list(seq.dtypes.astype(str)) != list(par.dtypes.astype(str)):
                problems.append(f"dtypes {list(seq.dtypes.astype(str))} != {list(par.dtypes.astype(str))}")
        elif isinstance(seq, pd.Series) and isinstance(par, pd.Series):
            if not seq.index.equals(par.index):
                problems.append("index differs")
            if str(seq.dtype) != str(par.dtype):
                problems.append(f"dtype {seq.dtype} != {par.dtype}")
            if seq.name != par.name:
                problems.append(f"name {seq.name!r} != {par.name!r}")
    if problems:
        print(f"[MISMATCH] {name}: {'; '.join(problems)}")
        print(f"    seq: {describe(seq)}")
        print(f"    par: {describe(par)}")
    else:
        print(f"[OK] {name}")


# ---------------- data ----------------
def mkdf(n, seed=0):
    rng = np.random.RandomState(seed)
    return pd.DataFrame(dict(a=rng.randint(0, 10, n), b=rng.rand(n)))


def mkmixed(n):
    return pd.DataFrame(
        {
            "i": np.arange(n, dtype="int64"),
            "f": np.arange(n, dtype="float64") + 0.5,
            "o": [f"s{i}" for i in range(n)],
            "bo": [bool(i % 2) for i in range(n)],
            "dt": pd.date_range("2020-01-01", periods=n),
            "cat": pd.Categorical([("x", "y")[i % 2] for i in range(n)]),
        }
    )


def add(x, k=0):
    return x + k


CASES = []


def case(name):
    def deco(f):
        CASES.append((name, f))
        return f
    return deco


# ---- axis sweep on numeric df ----
for size in (1000, 1, 2):
    for ax in (0, 1, "index", "columns"):
        def mk(size=size, ax=ax):
            df = mkdf(size)
            f = lambda x: x.max() - x.min() if True else None
            cmp(f"axis={ax!r} size={size} reduce(max-min)",
                lambda: df.apply(f, axis=ax), lambda: df.parallel_apply(f, axis=ax))
            g = lambda x: x * 2
            cmp(f"axis={ax!r} size={size} nonreduce(x*2)",
                lambda: df.apply(g, axis=ax), lambda: df.parallel_apply(g, axis=ax))
        CASES.append((f"sweep-{ax}-{size}", mk))


@case("invalid axis")
def _():
    df = mkdf(10)
    f = lambda x: x.sum()
    cmp("axis=2", lambda: df.apply(f, axis=2), lambda: df.parallel_apply(f, axis=2))
    cmp("axis='rows'", lambda: df.apply(f, axis="rows"), lambda: df.parallel_apply(f, axis="rows"))
    cmp("axis=None", lambda: df.apply(f, axis=None), lambda: df.parallel_apply(f, axis=None))


@case("empty frames")
def _():
    f = lambda x: x.sum()
    g = lambda x: x * 2
    empties = {
        "0rows-2cols": pd.DataFrame({"a": pd.Series([], dtype="int64"), "b": pd.Series([], dtype="float64")}),
        "3rows-0cols": pd.DataFrame(index=[0, 1, 2]),
        "fully-empty": pd.DataFrame(),
    }
    for nm, df in empties.items():
        for ax in (0, 1):
            cmp(f"empty {nm} axis={ax} sum", lambda df=df, ax=ax: df.apply(f, axis=ax),
                lambda df=df, ax=ax: df.parallel_apply(f, axis=ax))
            cmp(f"empty {nm} axis={ax} x*2", lambda df=df, ax=ax: df.apply(g, axis=ax),
                lambda df=df, ax=ax: df.parallel_apply(g, axis=ax))
        cmp(f"empty {nm} applymap", lambda df=df: df.applymap(lambda v: v),
            lambda df=df: df.parallel_applymap(lambda v: v))


@case("mixed dtypes")
def _():
    for n in (1, 5, 1000):
        df = mkmixed(n)
        cmp(f"mixed n={n} axis=1 row->str", lambda df=df: df.apply(lambda r: str(r["o"]) + str(r["i"]), axis=1),
            lambda df=df: df.parallel_apply(lambda r: str(r["o"]) + str(r["i"]), axis=1))
        cmp(f"mixed n={n} axis=0 col dtype", lambda df=df: df.apply(lambda c: str(c.dtype)),
            lambda df=df: df.parallel_apply(lambda c: str(c.dtype)))
        cmp(f"mixed n={n} axis=0 identity", lambda df=df: df.apply(lambda c: c),
            lambda df=df: df.parallel_apply(lambda c: c))
        cmp(f"mixed n={n} axis=1 identity", lambda df=df: df.apply(lambda r: r, axis=1),
            lambda df=df: df.parallel_apply(lambda r: r, axis=1))
        cmp(f"mixed n={n} applymap str", lambda df=df: df.applymap(str),
            lambda df=df: df.parallel_applymap(str))


@case("result_type")
def _():
    for n in (1, 4, 1000):
        df = mkdf(n)
        for rt in ("expand", "reduce", "broadcast", None):
            cmp(f"result_type={rt} n={n} list", lambda df=df, rt=rt: df.apply(lambda r: [1, 2], axis=1, result_type=rt),
                lambda df=df, rt=rt: df.parallel_apply(lambda r: [1, 2], axis=1, result_type=rt))
            cmp(f"result_type={rt} n={n} scalar", lambda df=df, rt=rt: df.apply(lambda r: r.sum(), axis=1, result_type=rt),
                lambda df=df, rt=rt: df.parallel_apply(lambda r: r.sum(), axis=1, result_type=rt))
        cmp(f"axis=0 result_type=expand n={n}", lambda df=df: df.apply(lambda c: [1, 2], axis=0, result_type="expand"),
            lambda df=df: df.parallel_apply(lambda c: [1, 2], axis=0, result_type="expand"))


@case("args/kwargs")
def _():
    df = mkdf(10)
    cmp("args+kwargs axis=1", lambda: df.apply(lambda r, m, bias=0: r.sum() * m + bias, axis=1, args=(2,), bias=3),
        lambda: df.parallel_apply(lambda r, m, bias=0: r.sum() * m + bias, axis=1, args=(2,), bias=3))
    cmp("args only axis=0", lambda: df.apply(add, args=(5,)), lambda: df.parallel_apply(add, args=(5,)))
    cmp("kwargs only axis=0", lambda: df.apply(add, k=5), lambda: df.parallel_apply(add, k=5))
    cmp("raw=True axis=1", lambda: df.apply(lambda r: r.sum(), axis=1, raw=True),
        lambda: df.parallel_apply(lambda r: r.sum(), axis=1, raw=True))
    cmp("raw=True axis=0", lambda: df.apply(lambda c: c.sum(), axis=0, raw=True),
        lambda: df.parallel_apply(lambda c: c.sum(), axis=0, raw=True))
    cmp("positional axis", lambda: df.apply(lambda r: r.sum(), 1), lambda: df.parallel_apply(lambda r: r.sum(), 1))


@case("weird indexes")
def _():
    n = 6
    dfs = {
        "nonunique-idx": pd.DataFrame({"a": range(n), "b": range(n)}, index=[0, 0, 1, 1, 2, 2]),
        "multiindex-rows": pd.DataFrame({"a": range(n), "b": range(n)},
                                        index=pd.MultiIndex.from_product([["x", "y"], [1, 2, 3]])),
        "multiindex-cols": pd.DataFrame(np.arange(4 * n).reshape(n, 4),
                                        columns=pd.MultiIndex.from_product([["A", "B"], ["u", "v"]])),
        "dup-cols": pd.DataFrame(np.arange(4 * n).reshape(n, 4), columns=["a", "a", "b", "b"]),
        "str-idx": pd.DataFrame({"a": range(n)}, index=[f"r{i}" for i in range(n)]),
    }
    for nm, df in dfs.items():
        for ax in (0, 1):
            cmp(f"{nm} axis={ax} reduce", lambda df=df, ax=ax: df.apply(lambda x: x.sum(), axis=ax),
                lambda df=df, ax=ax: df.parallel_apply(lambda x: x.sum(), axis=ax))
            cmp(f"{nm} axis={ax} nonreduce", lambda df=df, ax=ax: df.apply(lambda x: x * 2, axis=ax),
                lambda df=df, ax=ax: df.parallel_apply(lambda x: x * 2, axis=ax))
        cmp(f"{nm} applymap", lambda df=df: df.applymap(lambda v: v), lambda df=df: df.parallel_applymap(lambda v: v))


@case("1col / 1row / workers>data")
def _():
    df1c = pd.DataFrame({"a": range(5)})
    df1r = pd.DataFrame({"a": [1], "b": [2.0], "c": ["x"]})
    for nm, df in (("1col", df1c), ("1row", df1r)):
        for ax in (0, 1):
            cmp(f"{nm} axis={ax} reduce", lambda df=df, ax=ax: df.apply(lambda x: x.astype(str).sum(), axis=ax),
                lambda df=df, ax=ax: df.parallel_apply(lambda x: x.astype(str).sum(), axis=ax))
            cmp(f"{nm} axis={ax} nonreduce", lambda df=df, ax=ax: df.apply(lambda x: x.astype(str), axis=ax),
                lambda df=df, ax=ax: df.parallel_apply(lambda x: x.astype(str), axis=ax))


@case("udf returns list/dict/series")
def _():
    df = mkdf(6)
    cmp("axis=1 -> list", lambda: df.apply(lambda r: [1, 2, 3], axis=1),
        lambda: df.parallel_apply(lambda r: [1, 2, 3], axis=1))
    cmp("axis=1 -> dict", lambda: df.apply(lambda r: {"p": 1, "q": 2}, axis=1),
        lambda: df.parallel_apply(lambda r: {"p": 1, "q": 2}, axis=1))
    cmp("axis=1 -> Series", lambda: df.apply(lambda r: pd.Series({"p": 1, "q": 2}), axis=1),
        lambda: df.parallel_apply(lambda r: pd.Series({"p": 1, "q": 2}), axis=1))
    cmp("axis=0 -> list", lambda: df.apply(lambda c: [1, 2, 3]),
        lambda: df.parallel_apply(lambda c: [1, 2, 3]))
    cmp("axis=0 -> dict", lambda: df.apply(lambda c: {"p": 1}),
        lambda: df.parallel_apply(lambda c: {"p": 1}))
    cmp("axis=0 -> Series(diff len)", lambda: df.apply(lambda c: pd.Series([1, 2])),
        lambda: df.parallel_apply(lambda c: pd.Series([1, 2])))


@case("applymap na_action / NaN")
def _():
    df = pd.DataFrame({"a": [1.0, np.nan, 3.0], "b": [np.nan, 5.0, 6.0]})
    cmp("applymap NaN plain", lambda: df.applymap(lambda v: v * 2), lambda: df.parallel_applymap(lambda v: v * 2))
    cmp("applymap na_action=ignore", lambda: df.applymap(lambda v: v * 2, na_action="ignore"),
        lambda: df.parallel_applymap(lambda v: v * 2, na_action="ignore"))
    cmp("applymap na_action=ignore str", lambda: df.applymap(str, na_action="ignore"),
        lambda: df.parallel_applymap(str, na_action="ignore"))
    df2 = pd.DataFrame({"a": [1, 2], "b": [3, 4]})
    cmp("applymap kwargs", lambda: df2.applymap(add, k=10), lambda: df2.parallel_applymap(add, k=10))
    cmp("applymap 1000", lambda: mkdf(1000).applymap(lambda v: v + 1),
        lambda: mkdf(1000).parallel_applymap(lambda v: v + 1))
    cmp("parallel_map alias", lambda: df2.applymap(lambda v: v + 1), lambda: df2.parallel_map(lambda v: v + 1))


@case("exception propagation")
def _():
    df = mkdf(1000)
    def boom(x):
        raise ValueError("boom")
    cmp("axis=1 raise", lambda: df.apply(boom, axis=1), lambda: df.parallel_apply(boom, axis=1))
    cmp("axis=0 raise", lambda: df.apply(boom, axis=0), lambda: df.parallel_apply(boom, axis=0))
    cmp("applymap raise", lambda: df.applymap(boom), lambda: df.parallel_applymap(boom))


@case("mutating / dtype edge")
def _():
    df = mkmixed(1000)
    cmp("mixed 1000 axis=1 sum-num", lambda: df[["i", "f"]].apply(lambda r: r.sum(), axis=1),
        lambda: df[["i", "f"]].parallel_apply(lambda r: r.sum(), axis=1))
    b = pd.DataFrame({"x": [True, False, True, True], "y": [False, False, True, False]})
    cmp("bool axis=0 all", lambda: b.apply(lambda c: c.all()), lambda: b.parallel_apply(lambda c: c.all()))
    cmp("bool axis=1 any", lambda: b.apply(lambda r: r.any(), axis=1), lambda: b.parallel_apply(lambda r: r.any(), axis=1))
    cmp("bool applymap not", lambda: b.applymap(lambda v: not v), lambda: b.parallel_applymap(lambda v: not v))
    d = pd.DataFrame({"dt": pd.date_range("2021-01-01", periods=5), "n": range(5)})
    cmp("dt axis=0 max", lambda: d.apply(lambda c: c.max()), lambda: d.parallel_apply(lambda c: c.max()))
    cmp("dt axis=1 year", lambda: d.apply(lambda r: r["dt"].year, axis=1), lambda: d.parallel_apply(lambda r: r["dt"].year, axis=1))
    c = pd.DataFrame({"c": pd.Categorical(["a", "b", "a", "c"]), "n": range(4)})
    cmp("cat axis=0 identity", lambda: c.apply(lambda x: x), lambda: c.parallel_apply(lambda x: x))
    cmp("cat applymap str", lambda: c.applymap(str), lambda: c.parallel_applymap(str))


for name, fn in CASES:
    if only and only not in name:
        continue
    try:
        fn()
    except Exception:
        print(f"[HARNESS-ERROR] {name}")
        traceback.print_exc()
print("DONE")

import sys, glob, warnings
import numpy as np, pandas as pd
warnings.simplefilter("ignore")
from pandarallel import pandarallel

scenario = sys.argv[1]
pandarallel.initialize(nb_workers=2, progress_bar=False, use_memory_fs=None, verbose=0)
df = pd.DataFrame({"a": np.arange(100), "b": np.arange(100) * 1.0})

def boom(x):
    raise ValueError("boom")

def shm():
    return sorted(glob.glob("/dev/shm/pandarallel*"))

print("before:", shm())
if scenario == "ok":
    for _ in range(3):
        df.parallel_apply(lambda r: r.sum(), axis=1)
elif scenario == "fail":
    for _ in range(3):
        try:
            df.parallel_apply(boom, axis=1)
        except Exception as e:
            print("raised", type(e).__name__)
elif scenario == "badaxis":
    for _ in range(3):
        try:
            df.parallel_apply(lambda r: r.sum(), axis="rows")
        except Exception as e:
            print("raised", type(e).__name__)
elif scenario == "empty":
    for _ in range(3):
        pd.DataFrame().parallel_apply(lambda r: r.sum())
elif scenario == "unpicklable":
    class NotPicklable:
        def __reduce__(self):
            raise RuntimeError("nope")
    try:
        df.parallel_apply(lambda r: NotPicklable(), axis=1)
    except Exception as e:
        print("raised", type(e).__name__, e)
print("after:", shm())

