            bad.append((nb_item, nb_chunks, slices, f"coverage {idx}"))
        if len(slices) != min(nb_item, nb_chunks):
            bad.append((nb_item, nb_chunks, slices, f"nb slices {len(slices)}"))
        if any(s.start >= s.stop for s in slices):
            bad.append((nb_item, nb_chunks, slices, "empty slice"))
        sizes = [s.stop - s.start for s in slices]
        if max(sizes) - min(sizes) > 1:
            bad.append((nb_item, nb_chunks, slices, f"unbalanced {sizes}"))

# start_offset behaviour: chunk k must start start_offset items earlier (except first)
for nb_item in (1, 2, 5, 10, 23):
    for nb_chunks in (1, 2, 3, 4):
        for off in (0, 1, 3):
            base = chunk(nb_item, nb_chunks)
            off_s = chunk(nb_item, nb_chunks, start_offset=off)
            if len(base) != len(off_s):
                bad.append((nb_item, nb_chunks, off_s, f"len differs from base {base}"))
                continue
            for b, o in zip(base, off_s):
                if o.stop != b.stop:
                    bad.append((nb_item, nb_chunks, off_s, f"stop differs {b} {o}"))
                if o.start != max(0, b.start - off):
                    bad.append((nb_item, nb_chunks, off_s, f"start {o.start} != {max(0, b.start-off)} (off={off}, base={b})"))

print("chunk problems:", len(bad))
for b in bad[:25]:
    print("  ", b)
print("examples:", chunk(103, 4), chunk(1, 2), chunk(0, 2), chunk(2, 2), chunk(3, 2))
