import os, signal, sys, warnings
import numpy as np, pandas as pd
warnings.simplefilter("ignore")
from pandarallel import pandarallel

mode = sys.argv[1]
memfs = {"None": None, "False": False}[sys.argv[2]]
pandarallel.initialize(nb_workers=2, progress_bar=False, use_memory_fs=memfs, verbose=0)

df = pd.DataFrame({"a": np.arange(20), "b": np.arange(20) * 1.0})


class WeirdErr(Exception):
    def __init__(self, a, b):
        super().__init__(f"{a}-{b}")
        self.a, self.b = a, b


def killer(row):
    if row.name == 15:            # only in the second chunk
        os.kill(os.getpid(), signal.SIGKILL)
    return row.sum()


def weird(row):
    raise WeirdErr("x", "y")


print("start", flush=True)
