        r = df.parallel_apply(killer, axis=1)
        print("RESULT (no error!):", len(r), flush=True)
    elif mode == "weirdexc":
        try:
            df.apply(weird, axis=1)
        except Exception as e:
            print("seq:", type(e).__name__, e, flush=True)
        r = df.parallel_apply(weird, axis=1)
